analyze.mjs.text:
// Turns a resolved CAA record set (lookup.mjs) into a report: which
// certificate authorities are actually authorized to issue for this name,
// which records are malformed, and whether a critical-flagged, unrecognized
// property tag is silently blocking every CA that doesn't implement it --
// the finding a bare "here are your CAA records" lookup tool never surfaces,
// because it requires understanding RFC 8659's processing rules, not just
// displaying the record text.

import { parseIssueValue } from './parse.mjs';

/**
 * Certificate authorities most sites choose among, with the issuer domain
 * name each publishes for use in a CAA `issue`/`issuewild` value. Sourced
 * from each CA's own CAA-setup documentation and Let's Encrypt's own CAA
 * guide (https://letsencrypt.org/docs/caa/) at screening time -- a CA can
 * change or add an issuer domain, so treat this as a helpful shortlist, not
 * an authoritative registry, and always cross-check an unexpected result
 * against the CA's own current documentation before treating it as final.
 */
export const KNOWN_CAS = [
  { domain: 'letsencrypt.org', name: "Let's Encrypt" },
  { domain: 'pki.goog', name: 'Google Trust Services' },
  { domain: 'digicert.com', name: 'DigiCert' },
  { domain: 'sectigo.com', name: 'Sectigo' },
  { domain: 'amazontrust.com', name: 'Amazon Trust Services (AWS Certificate Manager)' },
  { domain: 'globalsign.com', name: 'GlobalSign' },
  { domain: 'ssl.com', name: 'SSL.com' },
  { domain: 'zerossl.com', name: 'ZeroSSL' },
];

const STANDARD_TAGS = new Set(['issue', 'issuewild', 'iodef']);

/**
 * @param {Array<{ok:boolean, flag?:number, critical?:boolean, tag?:string, value?:string, error?:string, raw?:string}>} records
 */
export function analyzeCaaSet(records) {
  const malformed = records.filter((r) => !r.ok).map((r) => ({ error: r.error, raw: r.raw }));
  const parsed = records.filter((r) => r.ok);

  const criticalUnknown = parsed.filter((r) => r.critical && !STANDARD_TAGS.has(r.tag));

  const issueRecords = parsed.filter((r) => r.tag === 'issue').map((r) => ({ ...r, parsedValue: parseIssueValue(r.value) }));
  const issuewildRecords = parsed.filter((r) => r.tag === 'issuewild').map((r) => ({ ...r, parsedValue: parseIssueValue(r.value) }));
  const iodefRecords = parsed.filter((r) => r.tag === 'iodef');

  const nonWildcardAuthorized = new Set(
    issueRecords.filter((r) => !r.parsedValue.disallowAll).map((r) => r.parsedValue.issuerDomain),
  );
  const nonWildcardDisallowAll = issueRecords.length > 0 && nonWildcardAuthorized.size === 0;

  // RFC 8659: issuewild governs wildcard certs when present at all; when no
  // issuewild record exists anywhere in the set (not even a disallow-all
  // one), issue applies to both. A single missed edge case here -- treating
  // "issuewild present but only as disallow-all" as "fall back to issue" --
  // is exactly the kind of fallback-rule mistake this tool exists to get
  // right, the same class of error security-headers-check documents for
  // CSP's frame-ancestors/default-src fallback.
  const wildcardAuthorized = issuewildRecords.length > 0
    ? new Set(issuewildRecords.filter((r) => !r.parsedValue.disallowAll).map((r) => r.parsedValue.issuerDomain))
    : new Set(nonWildcardAuthorized);
  const wildcardDisallowAll = issuewildRecords.length > 0 ? wildcardAuthorized.size === 0 : nonWildcardDisallowAll;

  const noCaaAnywhere = records.length === 0;

  function verdictFor(caDomain, authorizedSet, disallowAll) {
    if (criticalUnknown.length > 0) {
      return { authorized: false, reason: 'blocked-by-critical-unknown-tag' };
    }
    if (noCaaAnywhere) return { authorized: true, reason: 'no-caa-record-found' };
    if (disallowAll) return { authorized: false, reason: 'disallow-all' };
    if (authorizedSet.size === 0) return { authorized: true, reason: 'no-issue-property-in-set' };
    return { authorized: authorizedSet.has(caDomain.toLowerCase()), reason: authorizedSet.has(caDomain.toLowerCase()) ? 'named' : 'not-named' };
  }

  const caVerdicts = KNOWN_CAS.map((ca) => ({
    ...ca,
    nonWildcard: verdictFor(ca.domain, nonWildcardAuthorized, nonWildcardDisallowAll),
    wildcard: verdictFor(ca.domain, wildcardAuthorized, wildcardDisallowAll),
  }));

  return {
    noCaaAnywhere,
    malformed,
    criticalUnknown: criticalUnknown.map((r) => ({ tag: r.tag, value: r.value })),
    nonWildcardAuthorized: [...nonWildcardAuthorized],
    wildcardAuthorized: [...wildcardAuthorized],
    nonWildcardDisallowAll,
    wildcardDisallowAll,
    iodef: iodefRecords.map((r) => r.value),
    caVerdicts,
    /** True when this hostname has at least one issue worth a human's attention. */
    hasFindings: malformed.length > 0 || criticalUnknown.length > 0,
  };
}

/**
 * Checks one named or custom CA domain against an already-analyzed set, for
 * the CLI's `--ca` flag and the browser's "check a specific CA" field --
 * covers a CA outside the `KNOWN_CAS` shortlist without needing the table
 * to be exhaustive.
 */
export function verdictForCustomCa(analysis, caDomain) {
  const domain = String(caDomain).trim().toLowerCase();
  const known = KNOWN_CAS.find((ca) => ca.domain === domain);
  if (known) return analysis.caVerdicts.find((v) => v.domain === domain);
  const nonWildcard = analysis.criticalUnknown.length > 0
    ? { authorized: false, reason: 'blocked-by-critical-unknown-tag' }
    : analysis.noCaaAnywhere
      ? { authorized: true, reason: 'no-caa-record-found' }
      : analysis.nonWildcardDisallowAll
        ? { authorized: false, reason: 'disallow-all' }
        : analysis.nonWildcardAuthorized.length === 0
          ? { authorized: true, reason: 'no-issue-property-in-set' }
          : { authorized: analysis.nonWildcardAuthorized.includes(domain), reason: analysis.nonWildcardAuthorized.includes(domain) ? 'named' : 'not-named' };
  const wildcard = analysis.criticalUnknown.length > 0
    ? { authorized: false, reason: 'blocked-by-critical-unknown-tag' }
    : analysis.noCaaAnywhere
      ? { authorized: true, reason: 'no-caa-record-found' }
      : analysis.wildcardDisallowAll
        ? { authorized: false, reason: 'disallow-all' }
        : analysis.wildcardAuthorized.length === 0
          ? { authorized: true, reason: 'no-issue-property-in-set' }
          : { authorized: analysis.wildcardAuthorized.includes(domain), reason: analysis.wildcardAuthorized.includes(domain) ? 'named' : 'not-named' };
  return { domain, name: domain, nonWildcard, wildcard };
}

/** Combines a lookup result and its analysis into one per-hostname result. */
export function classify(hostname, lookup, requestedCa) {
  if (!lookup.ok) {
    return { hostname, category: 'lookup-error', error: lookup.error, lookup: null, analysis: null, requestedCaVerdict: null };
  }
  const analysis = analyzeCaaSet(lookup.records);
  const requestedCaVerdict = requestedCa ? verdictForCustomCa(analysis, requestedCa) : null;
  const category = analysis.malformed.length > 0 || analysis.criticalUnknown.length > 0
    ? 'has-findings'
    : requestedCaVerdict && !requestedCaVerdict.nonWildcard.authorized
      ? 'requested-ca-blocked'
      : 'clean';
  return { hostname, category, error: null, lookup, analysis, requestedCaVerdict };
}

/** Aggregates classify() results into the shape the CLI and the page render. */
export function buildReport(hostnames, results) {
  const errors = results.filter((r) => r.category === 'lookup-error');
  const findings = results.filter((r) => r.category === 'has-findings');
  const blocked = results.filter((r) => r.category === 'requested-ca-blocked');
  const clean = results.filter((r) => r.category === 'clean');
  return {
    hostnamesChecked: hostnames.length,
    results,
    errors,
    findingsCount: findings.length,
    blockedCount: blocked.length,
    cleanCount: clean.length,
    ok: errors.length === 0 && findings.length === 0 && blocked.length === 0,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: for each hostname given, resolves the CAA record set that actually
// governs certificate issuance (following RFC 8659's tree-walk up to the
// first ancestor that publishes one), reports every record's flag/tag/value,
// flags malformed records and a critical-flagged unrecognized tag, and --
// with --ca -- names whether one specific certificate authority is
// authorized to issue for it. Real DNS-over-HTTPS requests from your own
// machine; no request of any kind is ever sent to the hostname itself, only
// to Cloudflare's public resolver, reading DNS data already published for
// anyone to see.
//
//   node check.mjs <hostname> [<hostname> ...] [--ca <ca-domain>] [--json] [--timeout <ms>]
//
// Exit code 0 when every hostname resolves cleanly (and, with --ca, that CA
// is authorized); 1 when a hostname has a malformed record, a critical
// unrecognized tag, or (with --ca) the named CA is blocked; 2 on a usage
// error or a lookup that could not complete at all.

import { resolveCaaSet } from './lookup.mjs';
import { classify, buildReport, KNOWN_CAS } from './analyze.mjs';

function formatVerdict(label, v) {
  const mark = v.authorized ? 'OK  ' : 'FAIL';
  return `  [${mark}] ${label}: ${v.authorized ? 'authorized' : 'NOT authorized'} (${v.reason})`;
}

function formatText(report) {
  const lines = [];
  lines.push(`Hostnames checked: ${report.hostnamesChecked}`);
  lines.push('');

  for (const r of report.results) {
    lines.push(`== ${r.hostname} ==`);
    if (r.category === 'lookup-error') {
      lines.push(`  DNS lookup did not complete: ${r.error}`);
      lines.push('');
      continue;
    }
    const { lookup, analysis } = r;
    if (lookup.canonicalName !== lookup.queriedName) {
      lines.push(`  CNAME alias -> ${lookup.canonicalName}`);
    }
    if (analysis.noCaaAnywhere) {
      lines.push(`  No CAA record found anywhere from ${lookup.canonicalName} up to the top level -- any CA may issue.`);
    } else {
      lines.push(`  CAA record set found at: ${lookup.foundAtName}${lookup.foundAtName !== lookup.canonicalName ? ' (an ancestor, not the exact name)' : ''}`);
      for (const rec of lookup.records) {
        if (!rec.ok) {
          lines.push(`    !! MALFORMED: ${rec.error} (raw: ${rec.raw})`);
        } else {
          lines.push(`    ${rec.critical ? '[critical] ' : ''}${rec.tag} "${rec.value}"`);
        }
      }
    }
    if (analysis.criticalUnknown.length > 0) {
      lines.push(`  !! CRITICAL, UNRECOGNIZED TAG(S): ${analysis.criticalUnknown.map((c) => c.tag).join(', ')} -- any CA that does not implement this tag MUST refuse to issue for this name at all, per RFC 8659. In practice that is every public CA that doesn't specifically support it.`);
    }
    if (analysis.iodef.length > 0) {
      lines.push(`  Violation reports go to: ${analysis.iodef.join(', ')}`);
    }
    if (r.requestedCaVerdict) {
      lines.push(formatVerdict(`${r.requestedCaVerdict.name} (non-wildcard)`, r.requestedCaVerdict.nonWildcard));
      lines.push(formatVerdict(`${r.requestedCaVerdict.name} (wildcard)`, r.requestedCaVerdict.wildcard));
    }
    lines.push('');
  }

  if (report.errors.length > 0) {
    lines.push(`${report.errors.length} hostname(s) could not be looked up: ${report.errors.map((e) => `${e.hostname} (${e.error})`).join('; ')}`);
  }
  lines.push('');
  lines.push(
    'This reads public DNS CAA records and reports what RFC 8659 says they mean -- it does not ' +
      'contact the hostname, and a clean report is not a guarantee a given CA will actually issue ' +
      '(the CA makes that decision, and may apply checks of its own on top of this).',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  const hostnames = [];
  let json = false;
  let timeoutMs;
  let ca;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') json = true;
    else if (argv[i] === '--timeout') timeoutMs = Number(argv[++i]);
    else if (argv[i] === '--ca') ca = argv[++i];
    else if (!argv[i].startsWith('--')) hostnames.push(argv[i]);
  }
  return { hostnames, json, timeoutMs, ca };
}

/** Pure orchestration, kept separate from main() so tests can inject a fake resolver. */
export async function runCheck(hostnames, { resolveCaaSetFn = resolveCaaSet, timeoutMs, ca } = {}) {
  const results = await Promise.all(
    hostnames.map(async (hostname) => {
      const lookup = await resolveCaaSetFn(hostname, timeoutMs ? { timeoutMs } : undefined);
      return classify(hostname, lookup, ca);
    }),
  );
  return buildReport(hostnames, results);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.hostnames.length === 0) {
    console.error('Usage: node check.mjs <hostname> [<hostname> ...] [--ca <ca-domain>] [--json] [--timeout <ms>]');
    console.error(`Known CA shortlist: ${KNOWN_CAS.map((c) => c.domain).join(', ')} (or pass any other CA domain with --ca)`);
    process.exit(2);
  }

  const report = await runCheck(args.hostnames, { timeoutMs: args.timeoutMs, ca: args.ca });

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    console.log(formatText(report));
  }
  if (report.errors.length > 0) process.exit(2);
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

lookup.mjs.text:
// The only file in this venture that makes a DNS call, over Cloudflare's
// public DNS-over-HTTPS resolver -- the same shape and endpoint
// ventures/subdomain-takeover-check/lookup.mjs and
// ventures/email-auth-check/lookup.mjs already document. Zero-dependency:
// this module runs unmodified from check.mjs on the user's own machine and
// from index.html's <script type=module> in the visitor's own browser. No
// server of ours sits in between, and this tool never sends a request to the
// domain being checked at all -- only to the public resolver, reading DNS
// data the domain owner already published for anyone to see.

import { parseCaaData } from './parse.mjs';

const DOH_ENDPOINT = 'https://cloudflare-dns.com/dns-query';
const DEFAULT_TIMEOUT_MS = 8000;
const CAA_TYPE = 257;
const CNAME_TYPE = 5;
const MAX_TREE_WALK_LABELS = 20;

function stripTrailingDot(name) {
  return String(name).replace(/\.$/, '');
}

/** One raw DNS query (CAA or CNAME) via Cloudflare's public DoH JSON API. */
async function dohQuery(name, type, { fetchImpl = globalThis.fetch, timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  if (typeof fetchImpl !== 'function') {
    return { ok: false, error: 'no fetch implementation available in this runtime' };
  }
  const url = `${DOH_ENDPOINT}?name=${encodeURIComponent(name)}&type=${type}`;
  const controller = typeof AbortController === 'function' ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : null;
  try {
    const res = await fetchImpl(url, {
      headers: { accept: 'application/dns-json' },
      signal: controller ? controller.signal : undefined,
    });
    if (!res.ok) return { ok: false, error: `HTTP ${res.status} from the DNS resolver` };
    const body = await res.json();
    if (body.Status === 3) return { ok: true, nxdomain: true, answers: [] }; // NXDOMAIN
    if (body.Status !== 0) return { ok: false, error: `DNS resolver returned RCODE ${body.Status}` };
    return { ok: true, nxdomain: false, answers: body.Answer || [] };
  } catch (err) {
    const timedOut = err && err.name === 'AbortError';
    return { ok: false, error: timedOut ? 'timed out' : String((err && err.message) || err || 'unknown error') };
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/**
 * Looks up the CAA record set that actually governs certificate issuance for
 * `hostname`, per RFC 8659's tree-walk: a CA does not stop at the exact name
 * you point it at. It (1) follows a CNAME at the exact name once, since CAA
 * for an aliased name is evaluated at the alias's target, and (2) if the
 * resulting name carries no CAA records of its own, walks up one label at a
 * time -- `app.staging.example.com` -> `staging.example.com` ->
 * `example.com` -> `com` -- stopping at the first name that has ANY CAA
 * record set (even an empty, disallow-nothing one is still "found here" if
 * a zero-record answer at that exact name is distinguishable... in practice
 * DNS cannot distinguish "no CAA records" from "domain doesn't publish CAA",
 * so this keeps walking until it gets a non-empty answer or runs out of
 * labels, exactly matching what a real CA's own resolver does).
 *
 * Most simple "CAA lookup" tools query only the exact name you type and stop
 * -- which reports "no CAA record" (and therefore "any CA may issue") for a
 * subdomain whose *parent* domain actually restricts issuance, the single
 * most common source of the "why does my subdomain suddenly fail to renew"
 * confusion on Let's Encrypt's own community forum.
 *
 * @returns {{
 *   ok: boolean,
 *   queriedName: string,
 *   canonicalName: string,
 *   foundAtName: string|null,
 *   records: Array<{ok: true, flag:number, critical:boolean, tag:string, value:string} | {ok:false, error:string, raw:string}>,
 *   walkedNames: string[],
 *   error: string|null,
 * }}
 */
export async function resolveCaaSet(hostname, { fetchImpl, timeoutMs, dohQueryFn = dohQuery } = {}) {
  const queriedName = stripTrailingDot(hostname).toLowerCase();
  const opts = { fetchImpl, timeoutMs };

  // Step 1: a single CNAME hop at the exact name. A chain of CNAMEs pointing
  // through several aliases is rare for the name someone types into this
  // tool (that shape is CDN/load-balancer territory, not a bare "does my
  // domain have a working CAA record" question), so one hop covers the
  // common case -- a redirect to a hosting provider's own name -- without
  // this tool's tree-walk needing full loop protection on top of it.
  let canonicalName = queriedName;
  const cnameResult = await dohQueryFn(queriedName, CNAME_TYPE, opts);
  if (cnameResult.ok && !cnameResult.nxdomain) {
    const cname = cnameResult.answers.find((a) => a && a.type === CNAME_TYPE);
    if (cname) canonicalName = stripTrailingDot(cname.data).toLowerCase();
  }

  // Step 2: walk up from the canonical name until a non-empty CAA answer.
  const labels = canonicalName.split('.').filter(Boolean);
  const walkedNames = [];
  for (let dropped = 0; dropped <= Math.min(labels.length - 1, MAX_TREE_WALK_LABELS); dropped++) {
    const name = labels.slice(dropped).join('.');
    if (!name) break;
    walkedNames.push(name);
    const result = await dohQueryFn(name, CAA_TYPE, opts);
    if (!result.ok) {
      return { ok: false, queriedName, canonicalName, foundAtName: null, records: [], walkedNames, error: result.error };
    }
    const caaAnswers = result.answers.filter((a) => a && a.type === CAA_TYPE);
    if (caaAnswers.length > 0) {
      const records = caaAnswers.map((a) => parseCaaData(String(a.data)));
      return { ok: true, queriedName, canonicalName, foundAtName: name, records, walkedNames, error: null };
    }
    // Empty answer at this name: per RFC 8659, keep walking up. Reaching the
    // top-level domain with nothing found means no CAA record exists
    // anywhere in the tree, so every CA is authorized.
  }
  return { ok: true, queriedName, canonicalName, foundAtName: null, records: [], walkedNames, error: null };
}

parse.mjs.text:
// Parses a single CAA resource record's `data` field into
// `{ flag, critical, tag, value }`, and the `issue`/`issuewild` value's own
// grammar (RFC 8657) into `{ issuerDomain, disallowAll, parameters }`.
//
// Two wire formats have to be handled, not one. DNS-over-HTTPS resolvers
// return CAA `data` two different ways, and a parser tuned to only the
// friendlier one silently breaks on the other:
//
//   "0 issue \"letsencrypt.org\""          -- the RFC 8659 presentation format
//   "\\# 21 0005697373756..."              -- RFC 3597 "unknown RR" generic
//                                              hex encoding
//
// Cloudflare's own DoH JSON changelog (2026-07-28, "Improved DoH JSON
// formatting for additional record types") says CAA used to come back in the
// generic-hex form and was only switched to the presentation form that day --
// so a resolver that hasn't shipped the same fix, or a cached/older answer,
// can still hand back generic hex today. Decoding both is the difference
// between "this tool works" and "this tool works until it hits the one
// resolver that still answers the old way."

/** Decode an RFC 3597 generic-hex `data` string: `\# <len> <hex>`. */
function decodeGenericHex(raw) {
  const m = /^\\#\s+(\d+)\s+([0-9a-fA-F\s]*)$/.exec(raw.trim());
  if (!m) return null;
  const declaredLen = Number(m[1]);
  const hex = m[2].replace(/\s+/g, '');
  if (hex.length % 2 !== 0) {
    return { error: 'generic-hex CAA data has an odd number of hex digits' };
  }
  const bytes = [];
  for (let i = 0; i < hex.length; i += 2) bytes.push(parseInt(hex.slice(i, i + 2), 16));
  if (bytes.length !== declaredLen) {
    return { error: `generic-hex CAA data declares length ${declaredLen} but carries ${bytes.length} byte(s)` };
  }
  if (bytes.length < 2) return { error: 'generic-hex CAA data is too short to hold a flag and a tag length' };
  const flag = bytes[0];
  const tagLen = bytes[1];
  if (2 + tagLen > bytes.length) return { error: 'generic-hex CAA data\'s declared tag length runs past the record' };
  const tag = bytes.slice(2, 2 + tagLen).map((b) => String.fromCharCode(b)).join('');
  const value = bytes.slice(2 + tagLen).map((b) => String.fromCharCode(b)).join('');
  return { flag, tag, value };
}

/** Decode the RFC 8659 presentation format: `<flag> <tag> "<value>"`. */
function decodePresentation(raw) {
  const m = /^(\d{1,3})\s+([A-Za-z0-9][A-Za-z0-9-]*)\s+"((?:[^"\\]|\\.)*)"\s*$/.exec(raw.trim());
  if (!m) return null;
  const flag = Number(m[1]);
  const tag = m[2];
  const value = m[3].replace(/\\(.)/g, '$1');
  return { flag, tag, value };
}

/**
 * @returns {{ok: true, flag: number, critical: boolean, tag: string, value: string} |
 *           {ok: false, error: string, raw: string}}
 */
export function parseCaaData(raw) {
  if (typeof raw !== 'string' || raw.trim() === '') {
    return { ok: false, error: 'empty or missing CAA record data', raw: String(raw ?? '') };
  }
  const decoded = decodePresentation(raw) ?? decodeGenericHex(raw);
  if (!decoded) {
    return { ok: false, error: 'CAA data matched neither the presentation format nor RFC 3597 generic-hex', raw };
  }
  if (decoded.error) return { ok: false, error: decoded.error, raw };
  if (!Number.isInteger(decoded.flag) || decoded.flag < 0 || decoded.flag > 255) {
    return { ok: false, error: `flag byte ${decoded.flag} is out of the valid 0-255 range`, raw };
  }
  if ((decoded.flag & 0x7f) !== 0) {
    // RFC 8659: bit 0 (0x80, the "Issuer Critical Flag") is the only defined
    // bit; every other bit is reserved. A nonzero reserved bit is evidence
    // of a hand-built or generated record that got the flags byte wrong --
    // worth flagging rather than silently rounding down to "not critical".
    return { ok: false, error: `flag byte ${decoded.flag} sets a reserved bit outside the defined critical flag (0x80)`, raw };
  }
  const knownTags = new Set(['issue', 'issuewild', 'iodef']);
  const tagLower = decoded.tag.toLowerCase();
  if (!knownTags.has(tagLower) && !/^[a-z0-9-]+$/i.test(decoded.tag)) {
    return { ok: false, error: `tag "${decoded.tag}" is not a valid CAA property-tag token`, raw };
  }
  return { ok: true, flag: decoded.flag, critical: (decoded.flag & 0x80) !== 0, tag: tagLower, value: decoded.value };
}

/**
 * Parses an `issue`/`issuewild` value's own grammar (RFC 8659 §4.2, extended
 * by RFC 8657's CA-account-authorization parameters):
 *
 *   ";"                                              -- disallow every CA
 *   "letsencrypt.org"                                -- authorize one CA
 *   "letsencrypt.org; accounturi=...; validationmethods=dns-01"
 *                                                     -- authorize one CA,
 *                                                        restricted to a
 *                                                        specific account
 *                                                        and/or validation
 *                                                        method
 *
 * A hand-rolled parser that assumes "exactly one token" breaks on the third
 * shape -- this is the literal failure a DNSControl bug report records
 * ("CAA value does not contain 3 fields") against exactly this value shape.
 */
export function parseIssueValue(value) {
  const trimmed = (value ?? '').trim();
  if (trimmed === ';' || trimmed === '') {
    return { disallowAll: true, issuerDomain: null, parameters: {} };
  }
  const parts = trimmed.split(';').map((p) => p.trim()).filter((p) => p !== '');
  const issuerDomain = (parts.shift() ?? '').toLowerCase();
  const parameters = {};
  for (const part of parts) {
    const eq = part.indexOf('=');
    if (eq === -1) {
      parameters[part.toLowerCase()] = true; // a bare parameter name, malformed but preserved
      continue;
    }
    parameters[part.slice(0, eq).trim().toLowerCase()] = part.slice(eq + 1).trim();
  }
  return { disallowAll: issuerDomain === '', issuerDomain: issuerDomain || null, parameters };
}

